r=Path(__file__).resolve().parents[3];d=r/'data/venue_refs/floor_plans_v3/dual_unit_residential_floor_03';out=d/'wc118_transition_trial';dirs=[d/'wc117_support_clearance_trial',out];receipts=[json.loads((p/'candidate_cpu/candidate/render_receipt.json').read_text()) for p in dirs];sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
